(()=>{
const $=s=>document.querySelector(s), data=window.HELO_CATALOG, pages=$('#pages');
const names={wall:'From the wall',swatch:'Texture studies',detail:'Close ups',pin:'Pinned colours',wear:'Everyday forms',colour:'Colour notes',white:'White studies'};
const descriptions={wall:'A discovery from the HELO wall. Follow the folds, the colour and the small details that first caught your eye.',swatch:'A small piece, a whole world of texture. Look closely at the weave, the edges and the way light meets the surface.',detail:'Get a little closer. Explore the small variations that give a surface its character.',pin:'A colour, a pin, a starting point. Collect a shade and see where it takes your next idea.',wear:'From surface to silhouette. Explore relaxed shapes, quiet colours and the details of everyday clothing.',colour:'Colour changes the conversation. Bring these references together to discover an unexpected combination.',white:'White is never just white. Explore folds, shadows and subtle differences in the surface.'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=[],notes={},storageOK=true;
try{saved=JSON.parse(localStorage.getItem('helo-saved')||'[]');notes=JSON.parse(localStorage.getItem('helo-notes')||'{}');if(!Array.isArray(saved))saved=[];if(!notes||typeof notes!=='object')notes={};}catch(e){storageOK=false;}
saved=saved.filter(id=>data.some(p=>p.id===id));
function persist(){try{localStorage.setItem('helo-saved',JSON.stringify(saved));localStorage.setItem('helo-notes',JSON.stringify(notes));}catch(e){storageOK=false;toast('Saved for this visit. Browser storage is unavailable.');}}
let timer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2300);}
const route=()=>location.hash.slice(1)||'/';const go=p=>{if(route()===p)draw();else location.hash=p;};
const icon=(name)=>`<img class="ui-icon" src="assets/icons/${name}.png" alt="">`;
function footer(){return `<footer class="page-footer"><a href="#/" class="footer-logo">HELO</a><p>DISCOVER WHAT YOU’RE INTERESTED IN.</p><a href="#/about">ABOUT HELO ↗</a><span>Colour. Texture. Possibility.</span></footer>`;}
function saveButton(p){return `<button class="save ${saved.includes(p.id)?'selected':''}" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Remove':'Save'} ${p.title}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'✓':'+'}</button>`;}
function card(p){return `<article class="material-card"><a href="#/material/${p.id}" class="card-photo"><img src="${p.image}" alt="${p.colour} ${names[p.kind].toLowerCase()} ${p.id}" loading="lazy"></a>${saveButton(p)}<a href="#/material/${p.id}" class="card-caption"><span>${p.title}</span><span>↗</span></a><p>${names[p.kind]} <span>${p.colour.toUpperCase()}</span></p></article>`;}
function head(kicker,title,copy){return `<div class="page-intro"><p class="eyebrow">${kicker}</p><h2>${title}</h2><p class="intro-copy">${copy}</p></div>`;}
let browseKind='all',browseColour='all',searchTerm='';
function browse(){pages.innerHTML=`${head('THE MATERIAL LIBRARY / '+data.length+' REFERENCES','FOLLOW YOUR<br>CURIOSITY.','A collection of colours, textures and everyday forms. Find something that feels like you.')}<div class="library-tools"><div class="library-search">${icon('search')}<input id="libraryQuery" type="search" placeholder="Search colour, texture or clothing…" aria-label="Search materials" value="${esc(searchTerm)}"><button id="clearQuery" aria-label="Clear search">×</button></div><select id="colourSelect" aria-label="Filter by colour"><option value="all">ALL COLOURS</option>${['yellow','blue','green','orange','brown','white','natural','mixed'].map(x=>`<option ${browseColour===x?'selected':''} value="${x}">${x.toUpperCase()}</option>`).join('')}</select></div><div class="category-tabs" aria-label="Material categories"><button data-kind="all" class="${browseKind==='all'?'active':''}">ALL</button>${Object.entries(names).map(([k,n])=>`<button data-kind="${k}" class="${browseKind===k?'active':''}">${n.toUpperCase()}</button>`).join('')}</div><p class="results-count" id="resultsCount" aria-live="polite"></p><div class="material-grid" id="resultsGrid"></div>${footer()}`;
$('#libraryQuery').oninput=e=>{searchTerm=e.target.value;results();};$('#clearQuery').onclick=()=>{searchTerm='';$('#libraryQuery').value='';results();$('#libraryQuery').focus();};$('#colourSelect').onchange=e=>{browseColour=e.target.value;results();};pages.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{browseKind=b.dataset.kind;pages.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('active',x===b));results();});results();}
function results(){let q=searchTerm.trim().toLowerCase();const aliases={'黄色':'yellow','蓝色':'blue','绿色':'green','白色':'white','衣服':'wear','布料':'swatch','亚麻':'natural','橙色':'orange'};q=aliases[q]||q;const rows=data.filter(p=>(browseKind==='all'||p.kind===browseKind)&&(browseColour==='all'||p.colour===browseColour)&&`${p.title} ${p.kind} ${p.colour} ${names[p.kind]} ${p.kind==='wear'?'clothing shirt':''}`.toLowerCase().includes(q));$('#resultsCount').textContent=`${String(rows.length).padStart(2,'0')} / MATERIALS`;$('#resultsGrid').innerHTML=rows.length?rows.map(card).join(''):`<div class="empty-state"><span>↗</span><h3>KEEP EXPLORING.</h3><p>No materials match these filters.</p><button class="solid" id="resetFilters">SHOW ALL MATERIALS</button></div>`;if($('#resetFilters'))$('#resetFilters').onclick=()=>{browseKind=browseColour='all';searchTerm='';browse();};}
function material(id){const p=data.find(x=>x.id===id);if(!p){notFound();return;}const i=data.indexOf(p),related=data.filter(x=>x.id!==p.id&&(x.kind===p.kind||x.colour===p.colour)).slice(0,4);pages.innerHTML=`<div class="detail-breadcrumb"><a href="#/browse">← MATERIAL LIBRARY</a><span>${p.id.toUpperCase()}</span></div><div class="material-detail"><button class="detail-image" id="zoomImage" aria-label="Enlarge ${p.title}"><img src="${p.image}" alt="${p.title}"><span>CLICK TO LOOK CLOSER +</span></button><div class="detail-copy"><p class="eyebrow">${names[p.kind].toUpperCase()}</p><h2>${p.title.replace(/ (\d+)$/,'<br>$1')}</h2><p>${descriptions[p.kind]}</p><dl><div><dt>COLOUR</dt><dd>${p.colour.toUpperCase()}</dd></div><div><dt>COLLECTION</dt><dd>${names[p.kind]}</dd></div><div><dt>REFERENCE</dt><dd>${p.id.toUpperCase()}</dd></div></dl><button class="solid wide" data-save="${p.id}">${saved.includes(p.id)?'✓ SAVED TO YOUR BOARD':'+ SAVE TO YOUR BOARD'}</button><a class="text-link" href="#/board">VIEW YOUR BOARD ↗</a><details><summary>A NOTE ON THIS REFERENCE</summary><p>This is a visual reference from the HELO material collection. Colour and texture are shown for inspiration; composition and technical specifications have not been supplied.</p></details></div></div><div class="detail-pagination"><a href="#/material/${data[(i+data.length-1)%data.length].id}">← PREVIOUS REFERENCE</a><a href="#/material/${data[(i+1)%data.length].id}">NEXT REFERENCE →</a></div><div class="section-title"><h3>KEEP THE IDEAS COMING.</h3><a href="#/browse">EXPLORE ALL ↗</a></div><div class="material-grid related">${related.map(card).join('')}</div>${footer()}<dialog id="lightbox"><button class="close" aria-label="Close enlarged image">×</button><img src="${p.image}" alt="${p.title}"></dialog>`;$('#zoomImage').onclick=()=>$('#lightbox').showModal();$('#lightbox .close').onclick=()=>$('#lightbox').close();$('#lightbox').onclick=e=>{if(e.target===$('#lightbox'))$('#lightbox').close();};}
function board(){const rows=saved.map(id=>data.find(p=>p.id===id)).filter(Boolean);pages.innerHTML=`${head('YOUR PERSONAL COLLECTION','MAKE ROOM<br>FOR IDEAS.','Collect the things that catch your eye. Add a note, find a connection, make it yours.')}<div class="board-toolbar"><p>${rows.length} SAVED REFERENCES</p><button class="outline" id="exportBoard" ${rows.length?'':'disabled'}>EXPORT YOUR NOTES ↗</button></div><div class="board-grid">${rows.length?rows.map(p=>`<div class="board-item">${card(p)}<label for="note-${p.id}">YOUR IDEA</label><textarea id="note-${p.id}" data-note="${p.id}" maxlength="500" placeholder="What caught your eye?">${esc(notes[p.id]||'')}</textarea></div>`).join(''):`<div class="empty-state"><span class="empty-star">✳</span><h3>YOUR NEXT IDEA STARTS HERE.</h3><p>Tap + on a reference to keep it on your board.</p><a class="solid" href="#/browse">FIND YOUR FIRST TEXTURE ↗</a></div>`}</div><p class="storage-note">${storageOK?'Your collection and notes are saved in this browser.':'Your collection is available for this visit. Export your notes to keep a copy.'}</p>${footer()}`;pages.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{notes[t.dataset.note]=t.value;persist();});$('#exportBoard').onclick=()=>{const text='HELO — MY INSPIRATION BOARD\n\n'+rows.map(p=>`${p.title}\n${names[p.kind]} / ${p.colour}\n${notes[p.id]||''}\n`).join('\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='HELO-my-board.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your board notes have been exported.');};}
function about(){pages.innerHTML=`<div class="about-hero"><p class="eyebrow">HELLO, WE’RE HELO.</p><h2>A LITTLE<br>CURIOSITY.<br><span>A LOT OF<br>POSSIBILITY.</span></h2><div class="about-shape">✳</div><p>Start with a colour. Stay for a texture.<br>Let a small discovery become your next idea.</p></div><div class="about-story"><p class="eyebrow">A SPACE TO DISCOVER</p><div><h3>LOOK. COLLECT. CONNECT.</h3><p>HELO brings fabric, colour and everyday forms into one playful space. Move through the material wall, take a closer look, and keep the references that speak to you.</p><p>There is no set route. Follow a shade, notice a fold, or bring two unexpected textures together. Your collection is a place to begin.</p></div></div><div class="brand-colours"><div style="background:#0046a7;color:white"><span>01 / BLUE</span><strong>LOOK<br>CLOSER.</strong><small>#0046A7</small></div><div style="background:#fada03"><span>02 / YELLOW</span><strong>STAY<br>CURIOUS.</strong><small>#FADA03</small></div><div style="background:#ff7200"><span>03 / ORANGE</span><strong>TRY<br>SOMETHING.</strong><small>#FF7200</small></div><div style="background:#8debaf"><span>04 / MINT</span><strong>MAKE<br>CONNECTIONS.</strong><small>#8DEBAF</small></div></div><div class="brand-object"><img src="assets/brand-badges.webp" alt="HELO yellow staff badge and blue visitor badge" loading="lazy"><div><p class="eyebrow">THE IDENTITY, IN EVERYDAY LIFE</p><h3>SMALL DETAILS.<br>ONE SHARED LANGUAGE.</h3><p>The same bold type, rounded shapes and bright colour follow HELO from the screen into its printed identity.</p></div></div><div class="how-to"><h3>FIND YOUR OWN WAY.</h3><div><span>01</span><h4>EXPLORE</h4><p>Drag in any direction on the homepage, or browse the full material library.</p></div><div><span>02</span><h4>LOOK CLOSER</h4><p>Open a reference to see its details and discover related colours and forms.</p></div><div><span>03</span><h4>MAKE IT YOURS</h4><p>Save your favourites, add your ideas, and export your notes.</p></div></div><a href="#/browse" class="about-cta">WHAT WILL YOU<br>DISCOVER TODAY? <span>↗</span></a>${footer()}`;}
function notFound(){pages.innerHTML=`<div class="empty-state"><h2>LET’S FIND<br>ANOTHER WAY.</h2><p>This reference is not in the collection.</p><a href="#/browse" class="solid">BACK TO THE LIBRARY ↗</a></div>${footer()}`;}
const nav=document.querySelector('header nav');nav.innerHTML='<button id="search">SEARCH</button><a href="#/board" id="boardNav">MY BOARD <sup>0</sup></a><a href="#/about">ABOUT</a><button id="home">HOME</button>';
function updateCount(){$('#boardNav sup').textContent=saved.length;}updateCount();
$('#search').onclick=()=>{go('/browse');setTimeout(()=>$('#libraryQuery')?.focus(),0);};$('#home').onclick=()=>{reset();go('/');};$('#reset').onclick=()=>{reset();go('/');};
const browseLink=document.createElement('a');browseLink.className='home-library';browseLink.href='#/browse';browseLink.textContent='EXPLORE THE LIBRARY ↗';document.body.appendChild(browseLink);
pages.addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(!b)return;const id=b.dataset.save;if(saved.includes(id)){saved=saved.filter(x=>x!==id);toast('Removed from your board.');}else{saved.push(id);toast('Saved to your board.');}persist();updateCount();if(route()==='/board'){const top=pages.scrollTop;board();pages.scrollTop=top;}else if(route().startsWith('/material/')){b.textContent=saved.includes(id)?'✓ SAVED TO YOUR BOARD':'+ SAVE TO YOUR BOARD';if(b.classList.contains('save')){b.textContent=saved.includes(id)?'✓':'+';b.classList.toggle('selected',saved.includes(id));}b.setAttribute('aria-label',(saved.includes(id)?'Remove ':'Save ')+id);b.setAttribute('aria-pressed',saved.includes(id));}else{b.textContent=saved.includes(id)?'✓':'+';b.classList.toggle('selected',saved.includes(id));b.setAttribute('aria-pressed',saved.includes(id));b.setAttribute('aria-label',`${saved.includes(id)?'Remove':'Save'} ${data.find(p=>p.id===id).title}`);}});
function draw(){const path=route();const isHome=path==='/';document.body.classList.toggle('subpage',!isHome);pages.hidden=isHome;world.inert=!isHome;document.querySelector('#cursor').style.display='none';nav.querySelectorAll('a').forEach(a=>{a.removeAttribute('aria-current');if(a.hash===location.hash)a.setAttribute('aria-current','page');});if(!isHome){if(path==='/browse')browse();else if(path==='/board')board();else if(path==='/about')about();else if(path.startsWith('/material/'))material(path.slice(10));else notFound();pages.scrollTop=0;pages.focus({preventScroll:true});}document.title=`HELO — ${isHome?'Discover':path==='/browse'?'Material library':path==='/board'?'My board':path==='/about'?'About': 'Material reference'}`;}
addEventListener('hashchange',draw);draw();
const canvasIDs=Array.from({length:12},(_,i)=>'wall-'+String(i+1).padStart(2,'0'));
let down=null;world.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,moved:false};});world.addEventListener('pointermove',e=>{if(down&&Math.hypot(e.clientX-down.x,e.clientY-down.y)>7)down.moved=true;const hit=(window.heloHits||[]).find(h=>e.clientX>=h.x&&e.clientX<=h.x+h.w&&e.clientY>=h.y&&e.clientY<=h.y+h.h);$('#cursor').textContent=hit?'VIEW ↗':'DRAG';});world.addEventListener('pointerup',e=>{if(down&&!down.moved){const hit=(window.heloHits||[]).find(h=>e.clientX>=h.x&&e.clientX<=h.x+h.w&&e.clientY>=h.y&&e.clientY<=h.y+h.h);if(hit){vx=vy=0;go('/material/'+canvasIDs[hit.index]);}}down=null;});world.addEventListener('pointercancel',()=>down=null);
})();

